 X("tbl-p224-0582", None,
   [[C("3HP", rs=2), C("1 weekly dose missed"), C("If the missed dose is remembered within the next 2 days, continue to take the remaining doses according to the original schedule. If the missed dose is remembered > 2 days later, take the missed dose immediately, and change the schedule for weekly intake to the day the missed dose was taken, until treatment completion. This will avoid 2 weekly doses being taken fewer than 4 days apart.")],
    r("More than 1 weekly doses missed", "If treatment interruption occurred after at least 9 doses were taken within 12 weeks of starting, continue and complete the remaining doses, thus prolonging the total treatment duration to a maximum of 112 days. If ≥ 4 weekly doses are missed, consider restarting the full TPT course. If an individual has difficulty adhering to a weekly routine, consider dis continuing 3HP and offering an alternative regimen with daily dosing."),
    [C("1HP", rs=2), C("Less than 7 doses missed"), C("Continue and complete the remaining doses, thus prolonging the total treatment duration to a maximum of 6 weeks (42 days from starting TPT)")],
    r("More than 7 doses missed", "If < 7 consecutive doses were missed, consider restarting the complete course of the 1HP regimen. If > 7 doses were missed intermittently, continue and complete the remaining doses, thus prolonging the total treatment duration to a maximum of 6 weeks (42 days from starting TPT)"),
    [C("3HR, 4R, 6H, 6Lfx", rs=2), C("Less than 2 weeks"), C("Resume TPT and add the number of missed doses to the total treatment duration.<br/>Do not change the scheduled date of the next follow-up visit, but postpone the last follow-up visit by the number of extra days to compensate for missed doses. For example, if a child on 3HR misses 3 days of treatment, continue TPT for a total of 3 months + 3 days from the date of start.")],
    r("More than 2 weeks", "If treatment interruption occurs after more than 80% of doses in the regimen have been taken, continue and complete the remaining treatment as per the original plan. If less than 80% of doses in the regimen were taken, and the treatment course can still be completed within the expected treatment duration + 33% additional time, continue and complete the remaining treatment as per the original plan. For example, if an adult on 6H had taken only 120 doses by month 6, the remaining 62 doses can be taken in the next 2 months, without exceeding the 239-day limit. If < 80% of doses in the regimen were taken, and the treatment course cannot be completed within the expected time, consider restarting the full TPT course. A shorter regimen would be preferable.")],
   cap="Table 62: Management of TPT interruption or missed dose", pages=[224, 225],
   source_flags=["1HP 'More than 7 doses missed' row says 'If < 7 consecutive doses were missed, consider restarting'; the intended rule (WHO) is to restart if more than 7 consecutive doses are missed."]),
